// Compact, normalized force samples. Replay is limited to the procedural particle passes.
export class GestureTape{
 constructor(lab){this.lab=lab;this.mode='idle';this.clock=0;this.last=-1;this.force=new Float32Array(4);this.stroke=new Float32Array(2);this.camera=new Float32Array(5);}
 supported(){return this.lab.state.sceneId==='particle-web'||(this.lab.state.sceneId==='reactive-typography'&&this.lab.state.variants['reactive-typography']===11);}
 start(){if(!this.supported()||this.lab.recorder)return;this.lab.capture();const initial=structuredClone({...this.lab.state,gesture:null});this.lab.state.gesture={version:1,initial,frames:[]};this.lab.gpu.resetFeedback();this.clock=0;this.last=-1;this.mode='record';this.sync();}
 stop(){this.mode='idle';this.sync();this.lab.onUpdate();}
 replay(){const tape=this.lab.state.gesture;if(!tape?.frames?.length||this.lab.recorder)return;this.lab.load({...tape.initial,gesture:tape});this.lab.render();this.lab.gpu.resetFeedback();this.clock=0;this.mode='replay';this.sync();}
 reset(){this.stop();this.lab.state.gesture=null;this.sync();this.lab.onUpdate();}
 step(dt,force=[.5,.5,0,0],stroke=[0,0],camera=[0,0,1]){const s=this.lab.state,tape=s.gesture;this.clock+=dt;
 if(this.mode==='record'&&tape){if(this.clock-this.last>=1/30){tape.frames.push([this.clock,s.time,...force,...stroke,...camera].map(v=>Math.round(v*10000)/10000));this.last=this.clock;}if(this.clock>=60)this.stop();}
 if(this.mode==='replay'&&tape?.frames?.length){const frames=tape.frames;let index=this.index||0;if(index>=frames.length||frames[index][0]>this.clock)index=0;while(index+1<frames.length&&frames[index+1][0]<=this.clock)index++;this.index=index;const a=frames[index],b=frames[Math.min(index+1,frames.length-1)],k=b[0]===a[0]?0:Math.max(0,Math.min(1,(this.clock-a[0])/(b[0]-a[0])));s.time=a[1]+(b[1]-a[1])*k;for(let i=0;i<4;i++)this.force[i]=i===3?a[2+i]:a[2+i]+(b[2+i]-a[2+i])*k;for(let i=0;i<2;i++)this.stroke[i]=a[6+i]+(b[6+i]-a[6+i])*k;for(let i=0;i<5;i++)this.camera[i]=(a[8+i]??0)+((b[8+i]??0)-(a[8+i]??0))*k;if(this.clock>=frames.at(-1)[0])this.stop();return {force:this.force,stroke:this.stroke,camera:this.camera};}
 return {force,stroke,camera};}
 mount(){if(!this.supported())return;const host=document.createElement('div');host.className='inspector-block gesture-tape';host.innerHTML='<div class="block-heading">INTERACTION TAKE <span>PARTICLES / 60 S MAX</span></div><div class="composer-add"><button class="toolbtn" data-tape="record">● RECORD GESTURE</button><button class="toolbtn" data-tape="stop">■ STOP</button><button class="toolbtn" data-tape="replay">▶ REPLAY</button><button class="toolbtn" data-tape="reset">RESET TAKE</button></div><p class="micro-note" id="tape-status"></p>';this.lab.root.querySelector('.inspector-content').prepend(host);host.onclick=e=>{const action=e.target.closest('[data-tape]')?.dataset.tape;if(action==='record')this.start();if(action==='stop')this.stop();if(action==='replay')this.replay();if(action==='reset')this.reset();};this.sync();}
 sync(){const root=this.lab.root,frames=this.lab.state.gesture?.frames?.length||0;for(const button of root.querySelectorAll('[data-tape]')){const a=button.dataset.tape;button.disabled=a==='stop'?this.mode==='idle':this.mode!=='idle'||(a==='replay'&&!frames);}const status=root.querySelector('#tape-status');if(status)status.textContent=this.mode==='idle'?(frames?'TAKE SAVED / '+frames+' SAMPLES':'Record normalized forces and camera. Replay restores the starting composition.'):this.mode==='record'?'RECORDING / INTERACT WITH THE PARTICLES':'REPLAYING / RESTORED INITIAL STATE';for(const control of root.querySelectorAll('[data-gen-scene],[data-gen-param],#gen-look,#gen-reset,#gen-seed,#gen-variation,#gen-text,#gen-font,[data-gen-type]'))control.disabled=this.mode!=='idle';}
}
